(4476658, 644619, 82814, '<td valign="top">I like the title and the presentation - this is very well executed.</td>', 'I like the title and the presentation - this is very well executed.', '2008-02-11 01:29:53.000000', NULL, 1),
(4476836, 645566, 30712, '<td valign="top">This image would mean more if there were sharper elements in it.  In terms of composition all the action is at the top.  Cropping away some of the bottom of the image would give the picture more balance.</td>', 'This image would mean more if there were sharper elements in it.  In terms of composition all the action is at the top.  Cropping away some of the bottom of the image would give the picture more balance.', '2008-02-11 02:12:56.000000', NULL, 1),
(4476853, 645561, 30712, '<td valign="top">This image would be greatly improved if the mid-tones were give a bit of a lift.  At the moment it feels as if it is still raining.</td>', 'This image would be greatly improved if the mid-tones were give a bit of a lift.  At the moment it feels as if it is still raining.', '2008-02-11 02:17:13.000000', NULL, 1),
(4476866, 645359, 67258, '<td valign="top">Excellent work!</td>', 'Excellent work!', '2008-02-11 02:20:12.000000', NULL, 1),
(4476867, 645330, 30712, '<td valign="top">Tweaking the image to make those cloud edges sing more would put a smile on my face.  After their treatment the clouds might even show up a little as reflections in the water.</td>', 'Tweaking the image to make those cloud edges sing more would put a smile on my face.  After their treatment the clouds might even show up a little as reflections in the water.', '2008-02-11 02:20:20.000000', NULL, 1),
(4476897, 645572, 30712, '<td valign="top">Even if the camera shows up small in the image it is really not quite fitting the requirements of the subject - sorry!  A great shot otherwise.</td>', 'Even if the camera shows up small in the image it is really not quite fitting the requirements of the subject - sorry!  A great shot otherwise.', '2008-02-11 02:28:45.000000', NULL, 1),
(4476912, 644462, 45566, '<td valign="top">It''s a really nice shot, love the gold on the water.. it just feels to be more about the light than the reflection.  That doesn''t make a lot of sense I know, just a feeling</td>', 'It''s a really nice shot, love the gold on the water.. it just feels to be more about the light than the reflection.  That doesn''t make a lot of sense I know, just a feeling', '2008-02-11 02:33:19.000000', NULL, 1),
