(4478496, 645303, 38496, '<td valign="top">I''m not keen on the tilt.  Beautiful castle/reflection, though.</td>', 'I''m not keen on the tilt.  Beautiful castle/reflection, though.', '2008-02-11 16:32:21.000000', NULL, 1),
(4478501, 644710, 12733, '<td valign="top">That is a really interesting container. I hope you''ll let us know what it is after the challenge is over. Those bits of colored flare are too eye-catching; they pull attention away from the water and the reflections.</td>', 'That is a really interesting container. I hope you''ll let us know what it is after the challenge is over. Those bits of colored flare are too eye-catching; they pull attention away from the water and the reflections.', '2008-02-11 16:33:56.000000', NULL, 1),
(4478503, 645588, 31133, '<td valign="top">I like this... very symbolic and reflective on a couple of levels. I wonder if it might have even more impact with a strong background color ... but maybe that might be too cheesy? Either way, I like the composition too :-)</td>', 'I like this... very symbolic and reflective on a couple of levels. I wonder if it might have even more impact with a strong background color ... but maybe that might be too cheesy? Either way, I like the composition too :-)', '2008-02-11 16:34:42.000000', NULL, 1),
(4478504, 645443, 38496, '<td valign="top">beautiful.  I like the yellow windows, they add a nice touch of color. my only nit-pick is that the horizon is too centered.  I would have liked it more on a third line.  Maybe crop some of the foreground out.</td>', 'beautiful.  I like the yellow windows, they add a nice touch of color. my only nit-pick is that the horizon is too centered.  I would have liked it more on a third line.  Maybe crop some of the foreground out.', '2008-02-11 16:35:04.000000', NULL, 1),
(4478505, 644600, 12733, '<td valign="top">Interesting colors in the water. Is that the color of the water or the color of the light?</td>', 'Interesting colors in the water. Is that the color of the water or the color of the light?', '2008-02-11 16:35:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4478507, 644581, 38496, '<td valign="top">very serene</td>', 'very serene', '2008-02-11 16:35:24.000000', NULL, 1),
(4478510, 644392, 38496, '<td valign="top">love the color tone of this shoot.</td>', 'love the color tone of this shoot.', '2008-02-11 16:35:49.000000', NULL, 1),
(4478511, 645370, 31133, '<td valign="top">So much fun to see these giant "x"s in the sky and even more fun when there''s a reflection and that''s the challenge for the week!</td>', 'So much fun to see these giant "x"s in the sky and even more fun when there''s a reflection and that''s the challenge for the week!', '2008-02-11 16:35:50.000000', NULL, 1),
(4478512, 644632, 38496, '<td valign="top">needs a spot of color somewhere to add some interest</td>', 'needs a spot of color somewhere to add some interest', '2008-02-11 16:36:14.000000', NULL, 1),
(4478515, 644713, 38496, '<td valign="top">pretty.</td>', 'pretty.', '2008-02-11 16:36:33.000000', NULL, 1),
(4478517, 644752, 31133, '<td valign="top">This is gorgeous. Even the thumbnail is pretty. So delicate and a great choice with the portrait orientation. A clear 10 from me!</td>', 'This is gorgeous. Even the thumbnail is pretty. So delicate and a great choice with the portrait orientation. A clear 10 from me!', '2008-02-11 16:37:22.000000', NULL, 1),
(4478518, 643621, 12733, '<td valign="top">Almost dizzying, very mysterious - great picture.</td>', 'Almost dizzying, very mysterious - great picture.', '2008-02-11 16:37:31.000000', NULL, 1),
(4478519, 644247, 38496, '<td valign="top">hmm... how did you do this?  Looks cool.</td>', 'hmm... how did you do this?  Looks cool.', '2008-02-11 16:37:35.000000', NULL, 1),
(4478520, 644420, 38496, '<td valign="top">cool abstract look to this.</td>', 'cool abstract look to this.', '2008-02-11 16:38:50.000000', NULL, 1),
(4478522, 645325, 31133, '<td valign="top">Glad you decided to leave the dust on the smooth floor rather than clean it up. It adds to an already very emotional image. Only one niggle, and that''s probably pure jealousy on my part - it seems like part of the hand is blown, which distracts me a bit. But over all, very, very nice!</td>', 'Glad you decided to leave the dust on the smooth floor rather than clean it up. It adds to an already very emotional image. Only one niggle, and that''s probably pure jealousy on my part - it seems like part of the hand is blown, which distracts me a bit. But over all, very, very nice!', '2008-02-11 16:39:49.000000', NULL, 1),
(4478523, 644385, 12733, '<td valign="top">Nice, but too much black relative to picture. In particular, I would crop out or clone the two white blobs on the right.</td>', 'Nice, but too much black relative to picture. In particular, I would crop out or clone the two white blobs on the right.', '2008-02-11 16:39:56.000000', NULL, 1),
(4478527, 644336, 88254, '<td valign="top">I would like to have seen this in color!</td>', 'I would like to have seen this in color!', '2008-02-11 16:40:44.000000', NULL, 1),
(4478528, 644759, 88254, '<td valign="top">Nice shot but the reflection doesn''t show too much.</td>', 'Nice shot but the reflection doesn''t show too much.', '2008-02-11 16:41:23.000000', NULL, 1),
(4478529, 644766, 12733, '<td valign="top">Very pretty layered effect.</td>', 'Very pretty layered effect.', '2008-02-11 16:41:25.000000', NULL, 1),
(4478530, 643462, 38496, '<td valign="top">another one where I''m asking "how the heck?"  I hope we get an explanation.  It''s a gorgeous shot...</td>', 'another one where I''m asking "how the heck?"  I hope we get an explanation.  It''s a gorgeous shot...', '2008-02-11 16:41:33.000000', NULL, 1),
(4478531, 645392, 31133, '<td valign="top">Beautiful colors, although I have to say for me, it might be a little on the strong side. Also something about the crop is bothering me ... maybe the three trees needs some breathing room on the left? Looks like a very peaceful place.</td>', 'Beautiful colors, although I have to say for me, it might be a little on the strong side. Also something about the crop is bothering me ... maybe the three trees needs some breathing room on the left? Looks like a very peaceful place.', '2008-02-11 16:41:38.000000', NULL, 1),
(4478532, 645377, 88254, '<td valign="top">Not seeing a reflection...</td>', 'Not seeing a reflection...', '2008-02-11 16:42:00.000000', NULL, 1),
(4478533, 644769, 88254, '<td valign="top">Cool idea...</td>', 'Cool idea...', '2008-02-11 16:42:41.000000', NULL, 1),
(4478534, 645462, 38496, '<td valign="top">love the colors.</td>', 'love the colors.', '2008-02-11 16:42:44.000000', NULL, 1),
(4478538, 645378, 12733, '<td valign="top">Reflection on top? Why? It''s a really nice shot, but it looks like it was printed upside down!</td>', 'Reflection on top? Why? It''s a really nice shot, but it looks like it was printed upside down!', '2008-02-11 16:44:14.000000', NULL, 1),
(4478539, 645580, 31133, '<td valign="top">This was a clever idea, and very nice angle. The car is embarrassingly clean though :-) (just kidding ... I''m always wishing I could keep my nice car cleaner). I like how the sunset in the car is much richer in color than the view directly over the water.</td>', 'This was a clever idea, and very nice angle. The car is embarrassingly clean though :-) (just kidding ... I''m always wishing I could keep my nice car cleaner). I like how the sunset in the car is much richer in color than the view directly over the water.', '2008-02-11 16:45:28.000000', NULL, 1),
(4478540, 645595, 12733, '<td valign="top">Very pretty colors; almost unreal.</td>', 'Very pretty colors; almost unreal.', '2008-02-11 16:45:39.000000', NULL, 1),
(4478543, 645303, 31133, '<td valign="top">I really like the photograph. Can''t quite decide how I feel about the angled crop decision though. Excellent reflection on a very nice day in what looks like a fantastic location.</td>', 'I really like the photograph. Can''t quite decide how I feel about the angled crop decision though. Excellent reflection on a very nice day in what looks like a fantastic location.', '2008-02-11 16:46:44.000000', NULL, 1),
(4478547, 642986, 31133, '<td valign="top">This is kind of funny, in a way cartoonish thanks to the selective desat and the strong primary colors. I really like that red! Unfortunately, I''m not a huge selective de-sat fan, but if I were, I would like this a lot more. I do like the decisions you made for how to do the selective desaturation. Nice with the clear Car Wash sign.</td>', 'This is kind of funny, in a way cartoonish thanks to the selective desat and the strong primary colors. I really like that red! Unfortunately, I''m not a huge selective de-sat fan, but if I were, I would like this a lot more. I do like the decisions you made for how to do the selective desaturation. Nice with the clear Car Wash sign.', '2008-02-11 16:49:11.000000', NULL, 1),
(4478548, 644253, 31133, '<td valign="top">I guess if that is a puddle on the basement floor, it must be a very bad leak! This is kind of like an abstract painting, with the blurred edges around the puddle. It almost feels like I''m looking through a hole up to the ceiling (that''s what I thought at first, actually). I like the colors very much, but not sure the picture grabs me as much as it should.</td>', 'I guess if that is a puddle on the basement floor, it must be a very bad leak! This is kind of like an abstract painting, with the blurred edges around the puddle. It almost feels like I''m looking through a hole up to the ceiling (that''s what I thought at first, actually). I like the colors very much, but not sure the picture grabs me as much as it should.', '2008-02-11 16:51:24.000000', NULL, 1),
(4478553, 645464, 31133, '<td valign="top">I''m guessing from the title that this is resin or sap on a tree? Interesting abstract. Ah, I see the tree now in the bubbles ... that makes it way better, but also hard to figure out what these bubbles are. Extra point for making me think!</td>', 'I''m guessing from the title that this is resin or sap on a tree? Interesting abstract. Ah, I see the tree now in the bubbles ... that makes it way better, but also hard to figure out what these bubbles are. Extra point for making me think!', '2008-02-11 16:53:05.000000', NULL, 1),
(4478556, 644577, 31133, '<td valign="top">It might be my monitor, but this is almost too dark for me to appreciate properly. The black on the tarnished silver together with that beautiful polished wood (what I can see of it in the foreground) is a very appealing color and texture combo.</td>', 'It might be my monitor, but this is almost too dark for me to appreciate properly. The black on the tarnished silver together with that beautiful polished wood (what I can see of it in the foreground) is a very appealing color and texture combo.', '2008-02-11 16:55:07.000000', NULL, 1),
(4478564, 642736, 31133, '<td valign="top">Such a pretty scene with the birds. I wish the white from the water and the flagpole weren''t there, but otherwise, I think this is a bucolic, calming image. I like the soft colors in the background.</td>', 'Such a pretty scene with the birds. I wish the white from the water and the flagpole weren''t there, but otherwise, I think this is a bucolic, calming image. I like the soft colors in the background.', '2008-02-11 16:57:26.000000', NULL, 1),
(4478568, 643624, 31133, '<td valign="top">The black part in the bottom is distracting. I like the dynamic composition though, with the rings on the left and the clouds.</td>', 'The black part in the bottom is distracting. I like the dynamic composition though, with the rings on the left and the clouds.', '2008-02-11 16:58:27.000000', NULL, 1),
(4478570, 645462, 31133, '<td valign="top">I loved this one already as a thumbnail. The glow and the colors are fantastic. Congratulations ... I''d be willing to bet this does very well, and it should!</td>', 'I loved this one already as a thumbnail. The glow and the colors are fantastic. Congratulations ... I''d be willing to bet this does very well, and it should!', '2008-02-11 16:59:34.000000', NULL, 1),
(4478575, 645564, 31133, '<td valign="top">Well, you''ve definitely met the challenge. This kind of fish is so beautiful. It''s hard shooting through aquarium walls, though and I can see that the image quality suffered a bit from that. Also, there''s a bit too much going on with the background design, bubbles, and the green plant stem. Hope you don''t mind my imput, because I really am not trying to put your image or you down. You met the challenge, but the image needs some work in my opinion. Good luck and keep on shooting!</td>', 'Well, you''ve definitely met the challenge. This kind of fish is so beautiful. It''s hard shooting through aquarium walls, though and I can see that the image quality suffered a bit from that. Also, there''s a bit too much going on with the background design, bubbles, and the green plant stem. Hope you don''t mind my imput, because I really am not trying to put your image or you down. You met the challenge, but the image needs some work in my opinion. Good luck and keep on shooting!', '2008-02-11 17:02:16.000000', NULL, 1),
(4478578, 645503, 31133, '<td valign="top">Even though I can never, ever, ever get this perfect of a capture of milk or water drops, I''m going to be brave and give a bit of criticism ... hope you don''t mind. For me, the light is just too harsh. It''s an amazingly perfect drop shot though ... I just wish it could''ve been with much softer light.</td>', 'Even though I can never, ever, ever get this perfect of a capture of milk or water drops, I''m going to be brave and give a bit of criticism ... hope you don''t mind. For me, the light is just too harsh. It''s an amazingly perfect drop shot though ... I just wish it could''ve been with much softer light.', '2008-02-11 17:03:50.000000', NULL, 1),
(4478586, 645448, 55956, '<td valign="top">great colours and perspective.</td>', 'great colours and perspective.', '2008-02-11 17:07:21.000000', NULL, 1),
(4478597, 642845, 55956, '<td valign="top">very good idea! 8</td>', 'very good idea! 8', '2008-02-11 17:13:07.000000', NULL, 1),
(4478635, 644377, 66524, '<td valign="top">simple and effective, very lovely</td>', 'simple and effective, very lovely', '2008-02-11 17:30:31.000000', NULL, 1),
(4478639, 644752, 66524, '<td valign="top">very beautiful</td>', 'very beautiful', '2008-02-11 17:32:25.000000', NULL, 1),
(4478648, 645597, 66524, '<td valign="top">this is very clever!  I don''t think you need to coffee pot though - jmho.  It''s a great shot.</td>', 'this is very clever!  I don''t think you need to coffee pot though - jmho.  It''s a great shot.', '2008-02-11 17:35:34.000000', NULL, 1),
(4478653, 645564, 66524, '<td valign="top">I like your idea, but the colors seem muted and the background pattern distracts.</td>', 'I like your idea, but the colors seem muted and the background pattern distracts.', '2008-02-11 17:38:51.000000', NULL, 1),
(4478667, 645325, 66524, '<td valign="top">Very creative!  I like this a lot! B&amp;W, emotive qualities and set up are outstanding.</td>', 'Very creative!  I like this a lot! B&W, emotive qualities and set up are outstanding.', '2008-02-11 17:45:18.000000', NULL, 1),
(4478670, 645462, 66524, '<td valign="top">this has a pleasant soft focus that evokes morning serenity - well done!</td>', 'this has a pleasant soft focus that evokes morning serenity - well done!', '2008-02-11 17:47:25.000000', NULL, 1),
(4478673, 645558, 66524, '<td valign="top">I was tempted to dismiss this as cluttered, but then Victorian era settings did have a lot going on.  This photo evoked that sensibility for me and tells a story.  Well done!  I am glad I gave pause for your vision.</td>', 'I was tempted to dismiss this as cluttered, but then Victorian era settings did have a lot going on.  This photo evoked that sensibility for me and tells a story.  Well done!  I am glad I gave pause for your vision.', '2008-02-11 17:52:44.000000', NULL, 1),
(4478678, 644769, 66524, '<td valign="top">Needs sharper focus and better composition.  Your subject matter here could really pop with some practice.</td>', 'Needs sharper focus and better composition.  Your subject matter here could really pop with some practice.', '2008-02-11 17:56:59.000000', NULL, 1),
(4478696, 644743, 66524, '<td valign="top">this is lovely</td>', 'this is lovely', '2008-02-11 18:05:00.000000', NULL, 1),
(4478697, 645466, 86379, '<td valign="top">perfect title! nice shot.</td>', 'perfect title! nice shot.', '2008-02-11 18:05:08.000000', NULL, 1),
(4478699, 645334, 60805, '<td valign="top">the ripples really enhance this. well done 8</td>', 'the ripples really enhance this. well done 8', '2008-02-11 18:05:24.000000', NULL, 1),
(4478700, 645505, 60805, '<td valign="top">I would have liked this better if the handlebars were cropped out.</td>', 'I would have liked this better if the handlebars were cropped out.', '2008-02-11 18:06:51.000000', NULL, 1),
(4478702, 643278, 66524, '<td valign="top">title added a lot to the story here so I see your point of view - very nice!</td>', 'title added a lot to the story here so I see your point of view - very nice!', '2008-02-11 18:07:18.000000', NULL, 1),
(4478707, 644423, 66524, '<td valign="top">This is a strong photo! I felt pulled in right away! then settled on the cliffs - whoa!  what a ride!</td>', 'This is a strong photo! I felt pulled in right away! then settled on the cliffs - whoa!  what a ride!', '2008-02-11 18:09:30.000000', NULL, 1),
(4478709, 645436, 66524, '<td valign="top">clever</td>', 'clever', '2008-02-11 18:10:14.000000', NULL, 1),
(4478717, 643649, 66524, '<td valign="top">very creative, nice out of box approach</td>', 'very creative, nice out of box approach', '2008-02-11 18:14:35.000000', NULL, 1),
(4478721, 642845, 66524, '<td valign="top">nice work!</td>', 'nice work!', '2008-02-11 18:16:09.000000', NULL, 1),
(4478726, 645050, 66524, '<td valign="top">I like this a lot - just happens to be my taste</td>', 'I like this a lot - just happens to be my taste', '2008-02-11 18:18:06.000000', NULL, 1),
(4478731, 644420, 66524, '<td valign="top">This photo competes with itself - upper vs lower, like 2 different photos</td>', 'This photo competes with itself - upper vs lower, like 2 different photos', '2008-02-11 18:19:37.000000', NULL, 1),
