(4478739, 644766, 66524, '<td valign="top">stunning!  I wrote down who I think this is ;)</td>', 'stunning!  I wrote down who I think this is ;)', '2008-02-11 18:23:08.000000', NULL, 1),
(4478741, 645552, 66524, '<td valign="top">very nice!</td>', 'very nice!', '2008-02-11 18:23:57.000000', NULL, 1),
(4478745, 643704, 66524, '<td valign="top">wow!  I can''t wait to ask you about this photo!</td>', 'wow!  I can''t wait to ask you about this photo!', '2008-02-11 18:25:16.000000', NULL, 1),
(4478746, 645259, 66524, '<td valign="top">Do I know who this is???  I love this style!  Good luck in the challenge, can''t wait to see!</td>', 'Do I know who this is???  I love this style!  Good luck in the challenge, can''t wait to see!', '2008-02-11 18:27:40.000000', NULL, 1),
(4478752, 644720, 53316, '<td valign="top">Beautiful concept.</td>', 'Beautiful concept.', '2008-02-11 18:30:25.000000', NULL, 1),
(4478753, 645554, 53316, '<td valign="top">I love it! Great composition and contrast.</td>', 'I love it! Great composition and contrast.', '2008-02-11 18:30:43.000000', NULL, 1),
(4478759, 645572, 66524, '<td valign="top">your camera is in the shot! nice photo though</td>', 'your camera is in the shot! nice photo though', '2008-02-11 18:34:06.000000', NULL, 1),
(4478766, 645334, 78599, '<td valign="top">This would have been fantastic in the impressionism challenge! (this one too, I''m just saying:P) Great shot:D</td>', 'This would have been fantastic in the impressionism challenge! (this one too, I''m just saying:P) Great shot:D', '2008-02-11 18:37:50.000000', NULL, 1),
(4478773, 643462, 78599, '<td valign="top">Uh...confusing:D</td>', 'Uh...confusing:D', '2008-02-11 18:43:36.000000', NULL, 1),
(4478793, 645572, 78021, '<td valign="top">Interesting idea but DNMC.<br/> <br/>The chalenge stated: "Creatively photograph a reflecting surface that is not a mirror while keeping your camera out of the shot."<br/> <br/>Camera is clearly in the shot.</td>', 'Interesting idea but DNMC. The chalenge stated: "Creatively photograph a reflecting surface that is not a mirror while keeping your camera out of the shot." Camera is clearly in the shot.', '2008-02-11 19:01:29.000000', NULL, 1),
(4478806, 645505, 78021, '<td valign="top">I''ve often marvled at the view reflecting off of the headlight while riding a chromed up Harley.  Love the originality for this challenge. (not another bird/bridge/building reflecting off of water)<br/> <br/>Beautiful shot! 10</td>', 'I''ve often marvled at the view reflecting off of the headlight while riding a chromed up Harley.  Love the originality for this challenge. (not another bird/bridge/building reflecting off of water) Beautiful shot! 10', '2008-02-11 19:08:16.000000', NULL, 1),
(4478915, 645464, 90047, '<td valign="top">outstanding...</td>', 'outstanding...', '2008-02-11 20:04:42.000000', NULL, 1),
(4478931, 645592, 63551, '<td valign="top">Nice set up, with great colors.. Wish the spoon would have been up just a little bit more so as to include the entire basin. As is, you still get a high 8!</td>', 'Nice set up, with great colors.. Wish the spoon would have been up just a little bit more so as to include the entire basin. As is, you still get a high 8!', '2008-02-11 20:13:07.000000', NULL, 1),
(4478940, 644447, 64929, '<td valign="top">Love the shot but the "L" sign is distracting to the beauty, IMHO</td>', 'Love the shot but the "L" sign is distracting to the beauty, IMHO', '2008-02-11 20:18:35.000000', NULL, 1),
(4478945, 644619, 64929, '<td valign="top">LOVE the crisp reflection but not as fond as the diagonal perspective</td>', 'LOVE the crisp reflection but not as fond as the diagonal perspective', '2008-02-11 20:20:03.000000', NULL, 1),
(4478951, 644720, 63551, '<td valign="top">Yummm, what a tasty idea! I wish there were a little less on the bottom, and a little more on top. It would have brought it into the "3rds" of the picture, and made for a better comp.. Still gets a high 7 from me!</td>', 'Yummm, what a tasty idea! I wish there were a little less on the bottom, and a little more on top. It would have brought it into the "3rds" of the picture, and made for a better comp.. Still gets a high 7 from me!', '2008-02-11 20:24:48.000000', NULL, 1),
(4478974, 645510, 60805, '<td valign="top">Does''nt seem to be in focus and is a bit noisy. A noise reduction software like neatimage would help here.</td>', 'Does''nt seem to be in focus and is a bit noisy. A noise reduction software like neatimage would help here.', '2008-02-11 20:37:22.000000', NULL, 1),
(4478994, 645494, 61577, '<td valign="top">Very nice photo I like your use of neg space</td>', 'Very nice photo I like your use of neg space', '2008-02-11 20:47:06.000000', NULL, 1),
(4478998, 644342, 86379, '<td valign="top">wow this is really nice. well done!</td>', 'wow this is really nice. well done!', '2008-02-11 20:47:55.000000', NULL, 1),
(4478999, 644769, 61577, '<td valign="top">A bit blurry, I always have troubles shooting fish tanks as they are usually in dark spaces</td>', 'A bit blurry, I always have troubles shooting fish tanks as they are usually in dark spaces', '2008-02-11 20:48:35.000000', NULL, 1),
(4479000, 645259, 61577, '<td valign="top">Great shot the border works well</td>', 'Great shot the border works well', '2008-02-11 20:49:01.000000', NULL, 1),
(4479009, 644439, 83845, '<td valign="top">Very nice composition... the blow out on the left and the spots on the window are a little distracting :)</td>', 'Very nice composition... the blow out on the left and the spots on the window are a little distracting :)', '2008-02-11 20:53:59.000000', NULL, 1),
(4479017, 645422, 83845, '<td valign="top">I nice subtly feeling to this... but not sure where the reflections are?</td>', 'I nice subtly feeling to this... but not sure where the reflections are?', '2008-02-11 20:56:18.000000', NULL, 1),
