(4481182, 644164, 55892, '<td valign="top">Appealing green tones.  I''m having trouble identifying the reflections.</td>', 'Appealing green tones.  I''m having trouble identifying the reflections.', '2008-02-12 19:17:00.000000', NULL, 1),
