(4481600, 645554, 50641, '<td valign="top">excellent abstract</td>', 'excellent abstract', '2008-02-12 22:08:17.000000', NULL, 1),
(4481634, 644342, 83845, '<td valign="top">There are a lot of nice things in this photo.  I would love to see this in a print.  It''s really yellow top left, but great photo.</td>', 'There are a lot of nice things in this photo.  I would love to see this in a print.  It''s really yellow top left, but great photo.', '2008-02-12 22:18:03.000000', NULL, 1),
