(4488895, 643621, 50695, '<td valign="top">Reflections present an opportunity to create alternative worlds. You have done so, and this mysterious baroque world garners a Posthumous Yellow Ribbon.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'Reflections present an opportunity to create alternative worlds. You have done so, and this mysterious baroque world garners a Posthumous Yellow Ribbon. ', '2008-02-15 14:03:15.000000', NULL, 1),
(4488896, 643909, 50695, '<td valign="top">This reminds me of the story Yellow Wallpaper. See how the wallpaper has entered her mind? This strange frightening photo deserves at least a Posthumous Red Ribbon.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/redpost.jpg'', strrpos(''//blackyak.com/dpc/redpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/redpost.jpg"/></td>', 'This reminds me of the story Yellow Wallpaper. See how the wallpaper has entered her mind? This strange frightening photo deserves at least a Posthumous Red Ribbon. ', '2008-02-15 14:03:22.000000', NULL, 1),
(4488897, 645386, 50695, '<td valign="top">Stunning photograph. Masterfully divided composition creates endless visual interest. The Clarkean processing is mysterious and divine, purposefully extending the tree''s reflection into a nearby shrub, thereby shaking a perception that has already been stretched thin by the wide angle lens. This has Posthumous Blue Ribbon written all over it.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'Stunning photograph. Masterfully divided composition creates endless visual interest. The Clarkean processing is mysterious and divine, purposefully extending the tree''s reflection into a nearby shrub, thereby shaking a perception that has already been stretched thin by the wide angle lens. This has Posthumous Blue Ribbon written all over it. ', '2008-02-15 14:03:24.000000', NULL, 1),
(4488898, 645319, 50695, '<td valign="top">Gorgeous color and dynamic composition get a 10 from me.</td>', 'Gorgeous color and dynamic composition get a 10 from me.', '2008-02-15 14:03:49.000000', NULL, 1),
(4488899, 645470, 50695, '<td valign="top">This image is so frightening.<br/> <br/>How frightening is it?<br/> <br/>TEN frightening!</td>', 'This image is so frightening. How frightening is it? TEN frightening!', '2008-02-15 14:04:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4488900, 645554, 50695, '<td valign="top">Gorgeous colors and an energetic composition.</td>', 'Gorgeous colors and an energetic composition.', '2008-02-15 14:04:48.000000', NULL, 1),
(4488901, 645576, 50695, '<td valign="top">Great composition.</td>', 'Great composition.', '2008-02-15 14:05:05.000000', NULL, 1),
(4488902, 645435, 50695, '<td valign="top">Very cool use of transformative reflection.</td>', 'Very cool use of transformative reflection.', '2008-02-15 14:05:28.000000', NULL, 1),
(4488903, 642986, 50695, '<td valign="top">terrific candid and a fascinating image.</td>', 'terrific candid and a fascinating image.', '2008-02-15 14:05:49.000000', NULL, 1),
(4488904, 645436, 50695, '<td valign="top">Nicely found!</td>', 'Nicely found!', '2008-02-15 14:06:15.000000', NULL, 1),
(4488905, 644615, 50695, '<td valign="top">I love the purple water! It makes everything else seem beautifully golden.</td>', 'I love the purple water! It makes everything else seem beautifully golden.', '2008-02-15 14:06:43.000000', NULL, 1),
(4488906, 645464, 50695, '<td valign="top">Exciting and original image.</td>', 'Exciting and original image.', '2008-02-15 14:07:01.000000', NULL, 1),
(4488908, 644576, 50695, '<td valign="top">Gorgeous processing. The crop is perfect, but I still wonder about the dead-on view of the wading pool with typical perspective lines. Even so, it''s a real pleasure to look at.</td>', 'Gorgeous processing. The crop is perfect, but I still wonder about the dead-on view of the wading pool with typical perspective lines. Even so, it''s a real pleasure to look at.', '2008-02-15 14:08:38.000000', NULL, 1),
(4488910, 643624, 50695, '<td valign="top">Exciting composition from a disorienting angle. Well done!</td>', 'Exciting composition from a disorienting angle. Well done!', '2008-02-15 14:08:56.000000', NULL, 1),
(4488911, 645346, 50695, '<td valign="top">Fascinating use of reflection. This photo is a poem.</td>', 'Fascinating use of reflection. This photo is a poem.', '2008-02-15 14:09:26.000000', NULL, 1),
(4488912, 644656, 50695, '<td valign="top">Nice use of inversion to create a truly disorienting effect.</td>', 'Nice use of inversion to create a truly disorienting effect.', '2008-02-15 14:09:44.000000', NULL, 1),
(4488913, 645558, 50695, '<td valign="top">I don''t like shots-like-this but this is a really really good shot-like-this.</td>', 'I don''t like shots-like-this but this is a really really good shot-like-this.', '2008-02-15 14:10:19.000000', NULL, 1),
(4488914, 645572, 50695, '<td valign="top">Fun and enjoyable photo.</td>', 'Fun and enjoyable photo.', '2008-02-15 14:10:40.000000', NULL, 1),
(4488916, 643983, 50695, '<td valign="top">Neat. I want to find out what this is, exactly.</td>', 'Neat. I want to find out what this is, exactly.', '2008-02-15 14:11:05.000000', NULL, 1),
(4488918, 645592, 50695, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2008-02-15 14:11:14.000000', NULL, 1),
(4488920, 645566, 50695, '<td valign="top">Nice study of time.</td>', 'Nice study of time.', '2008-02-15 14:11:29.000000', NULL, 1),
(4488921, 644253, 50695, '<td valign="top">There''s something science-fiction-y about this. I like it.</td>', 'There''s something science-fiction-y about this. I like it.', '2008-02-15 14:11:44.000000', NULL, 1),
(4488922, 645334, 50695, '<td valign="top">very good example of this effect.</td>', 'very good example of this effect.', '2008-02-15 14:12:02.000000', NULL, 1),
(4488924, 645050, 50695, '<td valign="top">Lovely.</td>', 'Lovely.', '2008-02-15 14:12:10.000000', NULL, 1),
(4488928, 645355, 50695, '<td valign="top">house at the end of time. I love your title. Probably the best title in the challenge. I wonder if there should be an award for that??</td>', 'house at the end of time. I love your title. Probably the best title in the challenge. I wonder if there should be an award for that??', '2008-02-15 14:13:10.000000', NULL, 1),
(4488929, 644451, 50695, '<td valign="top">wow it looks like the building is on fire.</td>', 'wow it looks like the building is on fire.', '2008-02-15 14:13:14.000000', NULL, 1),
(4488949, 645330, 74534, '<td valign="top">Composition wise, it feels a bit incomplete with the bottom left corner leading the eye out of the image. Extra points for nailing a very difficult exposure though - great detail in the clouds, in the sun reflection, and even some detail salvaged in the water.</td>', 'Composition wise, it feels a bit incomplete with the bottom left corner leading the eye out of the image. Extra points for nailing a very difficult exposure though - great detail in the clouds, in the sun reflection, and even some detail salvaged in the water.', '2008-02-15 14:29:17.000000', NULL, 1),
(4488955, 644651, 74534, '<td valign="top">This is very good. The color contrast between the walls and the reflection does wonders. Very good composition, keeping both windows in the frame and creating the "break" between them. Negative points: maybe you could have waited for a more interesting reflection, to take full advantage of the good idea? The back of that car (Volvo?) somehow doesn''t make the most out of it. 8.</td>', 'This is very good. The color contrast between the walls and the reflection does wonders. Very good composition, keeping both windows in the frame and creating the "break" between them. Negative points: maybe you could have waited for a more interesting reflection, to take full advantage of the good idea? The back of that car (Volvo?) somehow doesn''t make the most out of it. 8.', '2008-02-15 14:31:40.000000', NULL, 1),
(4488957, 645346, 74534, '<td valign="top">A world reflected in another world... excellent capture seizing the core of this challenge.</td>', 'A world reflected in another world... excellent capture seizing the core of this challenge.', '2008-02-15 14:32:23.000000', NULL, 1),
(4488962, 645470, 74534, '<td valign="top">Hmmm.. almost missed the dog''s reflection - it makes the photo, but it''s very subtle. I wonder how many voters didn''t spend enough time on the image to see it.</td>', 'Hmmm.. almost missed the dog''s reflection - it makes the photo, but it''s very subtle. I wonder how many voters didn''t spend enough time on the image to see it.', '2008-02-15 14:33:14.000000', NULL, 1),
(4489086, 644448, 12733, '<td valign="top">A tight crop would have emphasized the reflection and eliminated the distracting room next door.</td>', 'A tight crop would have emphasized the reflection and eliminated the distracting room next door.', '2008-02-15 15:13:51.000000', NULL, 1),
(4489089, 644757, 12733, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2008-02-15 15:14:39.000000', NULL, 1),
(4489182, 645592, 31133, '<td valign="top">Very nice colors! I''d love to see a sharper dof in the foreground particularly, but really like this ... bet it would be awesome with just the spoon alone too.</td>', 'Very nice colors! I''d love to see a sharper dof in the foreground particularly, but really like this ... bet it would be awesome with just the spoon alone too.', '2008-02-15 15:55:04.000000', NULL, 1),
(4489186, 645330, 31133, '<td valign="top">The clouds are beautiful here. They''re the main part with interest ... very strong and good. The rest of it seems a bit ordinary, even if it is a nice spot.</td>', 'The clouds are beautiful here. They''re the main part with interest ... very strong and good. The rest of it seems a bit ordinary, even if it is a nice spot.', '2008-02-15 15:56:39.000000', NULL, 1),
(4489193, 645395, 31133, '<td valign="top">I think I can see where you''re going with this, but the light reflected off the rose petal in such a harsh way as to blow out part of it. The reflection part on the table is just right, however. I also feel that the white objects behind the rose are distracting. I like the picture orientation.</td>', 'I think I can see where you''re going with this, but the light reflected off the rose petal in such a harsh way as to blow out part of it. The reflection part on the table is just right, however. I also feel that the white objects behind the rose are distracting. I like the picture orientation.', '2008-02-15 15:59:11.000000', NULL, 1),
(4489205, 644326, 31133, '<td valign="top">The reflection in the water is gorgeous. The parts other than the water, however, are too processed (tonemapping or shadow/highlight) for my taste, particularly the greens. There''s a nice depth in the colors shown in the water that seems to have been removed from the rest of the image. The water part is really great though.</td>', 'The reflection in the water is gorgeous. The parts other than the water, however, are too processed (tonemapping or shadow/highlight) for my taste, particularly the greens. There''s a nice depth in the colors shown in the water that seems to have been removed from the rest of the image. The water part is really great though.', '2008-02-15 16:03:53.000000', NULL, 1),
(4489210, 645494, 31133, '<td valign="top">I like the composition, but think I would react better to the image if it the orange were in soft light rather than hard light. Also, I can''t really figure out what the title means or the white stuff in front (if it''s the reflection, it''s confusing to me).</td>', 'I like the composition, but think I would react better to the image if it the orange were in soft light rather than hard light. Also, I can''t really figure out what the title means or the white stuff in front (if it''s the reflection, it''s confusing to me).', '2008-02-15 16:05:57.000000', NULL, 1),
