(4491839, 645600, 83313, '<td valign="top">Kind of cool looking. I like colors in the reflected image, but not the car window part of the shot. The white car in the background draws my eye away.</td>', 'Kind of cool looking. I like colors in the reflected image, but not the car window part of the shot. The white car in the background draws my eye away.', '2008-02-17 01:38:42.000000', NULL, 1),
(4491846, 643909, 83313, '<td valign="top">Almost called this a shoehorn shot, but the pattern of the wallpaper on her forehead indicates this is indeed a reflection. I''d like to know how you did this. I hope you detail how you captured this image in the accompanying notes for the entry.</td>', 'Almost called this a shoehorn shot, but the pattern of the wallpaper on her forehead indicates this is indeed a reflection. I''d like to know how you did this. I hope you detail how you captured this image in the accompanying notes for the entry.', '2008-02-17 01:41:18.000000', NULL, 1),
(4491850, 644015, 83313, '<td valign="top">Gorgeoud blues, but I think the reflected buildings are a bit too far off. Cropping in a little closer would have worked well.</td>', 'Gorgeoud blues, but I think the reflected buildings are a bit too far off. Cropping in a little closer would have worked well.', '2008-02-17 01:42:40.000000', NULL, 1),
(4491853, 645422, 83313, '<td valign="top">The reflections are a fairly minor element in this image, but I really like it.</td>', 'The reflections are a fairly minor element in this image, but I really like it.', '2008-02-17 01:43:57.000000', NULL, 1),
