(4493351, 645599, 67697, '<td valign="top">The IR makes this look so beautiful.  I love the very dark water and sky.  They contrast well with the plant colors.</td>', 'The IR makes this look so beautiful.  I love the very dark water and sky.  They contrast well with the plant colors.', '2008-02-17 22:40:44.000000', NULL, 1),
(4493360, 644116, 67697, '<td valign="top">This looks like places I have visited recently.  I like seeing the tops of the trees reflected in the water.  I would like to have seen a boost in contrast to add some punch to that reflection and to create some more depth in the light shining thru the trees in the background.<br/> <br/>EDIT to add after the challenge:  They must use this same kind of boardwalk at all the state parks in Ohio lol.  <br/><br/><i>Message edited by author 2008-02-18 00:19:53.</i></td>', 'This looks like places I have visited recently.  I like seeing the tops of the trees reflected in the water.  I would like to have seen a boost in contrast to add some punch to that reflection and to create some more depth in the light shining thru the trees in the background. EDIT to add after the challenge:  They must use this same kind of boardwalk at all the state parks in Ohio lol.  ', '2008-02-17 22:43:22.000000', '2008-02-18 00:19:53.000000', 1),
(4493362, 645332, 65234, '<td valign="top">Nice colors and sharpness.</td>', 'Nice colors and sharpness.', '2008-02-17 22:44:35.000000', NULL, 1),
