(4494385, 644702, 3724, '<td valign="top">Formal bridge architectural - quiet, soft, misty landscape environ. A most appropriate subdued colour edit. Beautifully composed, enjoyable, proportional &amp; balanced. Very pretty.</td>', 'Formal bridge architectural - quiet, soft, misty landscape environ. A most appropriate subdued colour edit. Beautifully composed, enjoyable, proportional & balanced. Very pretty.', '2008-02-18 11:32:04.000000', NULL, 0),
